// The pictures given, as a list of at most 10 (FLUX 3 Klein's references): a list, one picture, or a list written
// as JSON; none at all makes a picture from the prompt alone
let list = pictures;
if (typeof list === 'string') {
  const t = list.trim();
  if (t.startsWith('[')) { try { list = JSON.parse(t); } catch { list = [t]; } } else list = t ? [t] : [];
}
list = (Array.isArray(list) ? list : list ? [list] : [])
  .map((p) => (p && typeof p === 'object' ? p.url || p.file || p.dataUrl || p.path : p))
  .filter((p) => typeof p === 'string' && p.trim())
  .map((p) => p.trim());
if (list.length > 10) throw new Error(`FLUX 3 Klein takes at most 10 pictures; ${list.length} were given`);
return list;

// What the enhancer is asked (as BFL's prompt upsampler is: the references shown to it first, in order)
const n = Array.isArray(given) ? given.length : 0;
return n
  ? `Reference images follow in order (the first image, the second image, ...): ${n} of them.\nUser request: ${request}\nOutput the caption.`
  : `User request: ${request}\nOutput the caption.`;

// What the reviewer is asked: the person's own request and the caption the picture was made from (it sees the result
// alone: a small vision model shown the references as well mistook one for the other)
const n = Array.isArray(given) ? given.length : 0;
const from = n ? `It was made from ${n === 1 ? 'a reference picture' : `${n} reference pictures`} and this caption, which describes the whole picture` : 'It was made from this caption';
return `The person asked for: ${request}\n\n${from}: ${caption}\n\nCheck the picture against what the person asked for and the caption.`;

// The prompt for this try: the enhanced one, and on a retry the last review's fix with it (a model told what to
// get right this time; the review read as the step before it left it, the loop's last try). In a layout the fix goes
// after its summary's caption, the layout kept whole.
const last = nodes.verdict;
const fix = attempt > 1 && last && typeof last.fix === 'string' ? last.fix.trim() : '';
const made = caption && typeof caption === 'object';
const base = made ? caption.prompt : caption;
if (!fix) return base;
if (made && caption.layout) {
  const layout = JSON.parse(base);
  layout.summary.caption = `${layout.summary.caption} ${fix}`;
  return JSON.stringify(layout);
}
return `${base}\n\n${fix}`;

data.systemPrompt:
You check a picture an image model made by editing or combining reference pictures, against what the person asked for and the caption it was made from, which describes the whole picture to make. Reply with JSON alone, no prose and no code fence, in exactly this shape:
{"pass": true or false, "issues": ["each real problem, in a few words"], "fix": "one sentence saying what the picture must show instead, as an instruction to the painter, or empty", "background": "plain" (an empty, even background), "pattern" (a texture, or small shapes or copies repeated across it) or "scene" (a place, a wall, a table), "text": {"requested": [each word or phrase the request asks to be written in the picture, exactly as asked: lettering, never the things it shows], "found": [each word or phrase you can read in the picture, letter by letter, as many times as it is written there (at most 3)]}}
Pass when the picture shows what the person asked for (what the request changes is changed, what it combines is combined) and matches the caption's description of the rest. Any text asked for must be exact, letter by letter. Detail neither mentions is not an issue. Fail only for a problem the person would notice. The text lists hold the words alone; leave them empty where there is no text.

data.code:
// Pass or try again: the review read from its reply (a reply that is not JSON cannot fail the picture: it is kept
// as text, the picture passed unchecked), with the picture's file reference. The lettering is checked here too: the
// reviewer lists what it reads, and each phrase that must be there has to be among it (a small vision model reading
// a picture is reliable; one judging whether it matches is lenient)
const text = String(review == null ? '' : review).trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
// (a reply cut short, as one listing a picture's repeated text runs out of room, closed and read as far as it goes)
const closed = (t) => {
  const open = [];
  let inString = false, escaped = false;
  for (const ch of t) {
    if (inString) { if (escaped) escaped = false; else if (ch === '\\') escaped = true; else if (ch === '"') inString = false; continue; }
    if (ch === '"') inString = true;
    else if (ch === '{') open.push('}');
    else if (ch === '[') open.push(']');
    else if (ch === '}' || ch === ']') open.pop();
  }
  return t + (inString ? '"' : '') + open.reverse().join('');
};
const parsed = (t) => { try { return JSON.parse(t); } catch { return null; } };
const at = text.indexOf('{');
let found = at < 0 ? null : parsed(text.slice(at, text.lastIndexOf('}') + 1)) || parsed(closed(text.slice(at)));
if (!found && /"pass"\s*:\s*false/.test(text)) found = { pass: false, issues: ['the review was cut short'] };
const checked = !!found && typeof found.pass === 'boolean';
const issues = checked && Array.isArray(found.issues) ? found.issues.filter((x) => typeof x === 'string' && x.trim()) : [];
const words = (s) => String(s).toUpperCase().replace(/[^A-Z0-9\u00C0-\uFFFF]+/g, ' ').trim();
const lists = checked && found.text && typeof found.text === 'object' ? found.text : {};
const strings = (v) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string' && words(x)) : []);
const read = ` ${strings(lists.found).map(words).join(' ')} `;
// (each piece of a layout's wording, or each phrase a caption quotes: the enhancer quotes exactly the lettering the
// picture must show, the request's own and, for an edit, what the references show that the request leaves alone)
const must = caption && typeof caption === 'object' ? (Array.isArray(caption.lettering) ? caption.lettering.slice() : []) : [];
if (!(caption && typeof caption === 'object')) String(caption == null ? '' : caption).replace(/["\u201C]([^"\u201D]{1,60})["\u201D]/g, (all, q) => { must.push(q); return all; });
const asked = must.map(words).filter(Boolean);
const phrases = [...new Set(asked)];
const said = new Map(must.map((m) => [words(m), m.trim()]));
const as = (p) => said.get(p) || p;
const missing = checked ? phrases.filter((p) => !read.includes(` ${p} `)) : [];
for (const p of missing) issues.push(`the text "${as(p)}" is not in the picture`);
// (each phrase as many times as it is asked for: a distilled model writes a name twice)
const times = (p) => { let n = 0; for (let i = read.indexOf(` ${p} `); i >= 0; i = read.indexOf(` ${p} `, i + p.length + 1)) n++; return n; };
const doubled = checked ? phrases.filter((p) => times(p) > asked.filter((a) => a === p).length) : [];
for (const p of doubled) issues.push(`the text "${as(p)}" is written more than once`);
// (a designed picture, a layout's, has its own lettering and nothing else)
const own = new Set(phrases.join(' ').split(' '));
const designed = !!(caption && typeof caption === 'object' && caption.layout);
const extra = checked && designed ? [...new Set(read.trim().split(/\s+/).filter((w) => w.length > 1 && !own.has(w)))] : [];
if (extra.length) issues.push(`text that was not asked for: ${extra.slice(0, 6).join(' ')}`);
const fix = [
  checked && typeof found.fix === 'string' ? found.fix.trim() : '',
  ...missing.map((p) => `The text "${as(p)}" must be written in it, exactly.`),
  ...doubled.map((p) => `The text "${as(p)}" is written once only.`),
  extra.length ? `The only lettering is ${phrases.map((p) => `"${as(p)}"`).join(' and ')}.` : '',
].filter(Boolean).map((t) => (/[.!?]$/.test(t) ? t : `${t}.`)).join(' ');
return {
  pass: checked ? found.pass === true && !missing.length && !doubled.length && !extra.length : true,
  checked,
  attempt,
  image: (made && made.file) || image,
  seed: made && made.seed != null ? made.seed : null,
  issues,
  fix,
  text: checked ? { requested: strings(lists.requested), quoted: must, found: strings(lists.found), missing, doubled, extra } : null,
  review: checked ? null : text,
};

// The flow's answer: the picture (its file's URL, never the picture itself), whether it passed, and each try's
// findings. The first try that passed, else the try with the fewest issues (the latest of those).
const tries = Array.isArray(attempts) ? attempts.filter((t) => t && typeof t === 'object') : [];
let best = tries.find((t) => t.pass) || null;
if (!best) for (const t of tries) if (!best || t.issues.length <= best.issues.length) best = t;
return {
  image: best ? best.image : null,
  pass: !!(best && best.pass),
  checked: !!(best && best.checked),
  tries: tries.length,
  issues: best ? best.issues : [],
  text: best ? best.text : null,
  prompt,
  caption: caption && typeof caption === 'object' ? caption.described : caption,
  layout: !!(caption && typeof caption === 'object' && caption.layout),
  attempts: tries.map((t) => ({ image: t.image, pass: t.pass, issues: t.issues, seed: t.seed })),
};
